# <<< STATIC

# >>> CHOICES
if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_bin() {
    if _argc_util_has_path_prefix; then
        _argc_util_comp_path
        return 0
    fi
    local root
    root="$(_argc_util_path_search_parent -p package.json)"
    if [[ -n "$root" && -d "$root/node_modules/.bin" ]]; then
        local entry
        for entry in "$root"/node_modules/.bin/*; do
            if [[ -f "$entry" && -x "$entry" ]]; then
                printf '%s\n' "${entry##*/}"
            fi
        done
    fi
    _argc_util_comp_command
}

_choice_config_key() {
    pnpm config list --json 2>/dev/null | jq -b -r 'keys[]' 2>/dev/null
}

_choice_exec() {
    _helper_local_package_bins
    _helper_cached_package_bins
}

_choice_exec_args() {
    if [[ "${#argc__positionals[@]}" -lt 2 ]]; then
        _choice_exec
        return 0
    fi
    local package="${argc__positionals[0]}"
    case "$package" in
        @*/*@*) package="${package%@*}" ;;
        @*) ;;
        *@*) package="${package%@*}" ;;
    esac
    argc__positionals[0]="$package"
    _argc_util_comp_subcommand 0
}

_choice_installed_package() {
    local pkg
    pkg="$(_helper_pkg_json)"
    [[ -n "$pkg" ]] || return 0
    jq -b -r '[(.dependencies // {}), (.devDependencies // {}), (.optionalDependencies // {}), (.peerDependencies // {})]
        | map(keys) | add // [] | .[]' "$pkg" 2>/dev/null
}

_choice_pkg_key() {
    local pkg
    pkg="$(_argc_util_path_search_parent package.json)"
    [[ -n "$pkg" ]] || return 0
    jq -b -r 'keys[]' "$pkg" 2>/dev/null
}

_choice_pkg_pair() {
    _argc_util_mode_kv =
    if [[ -z "$argc__kv_prefix" ]]; then
        _choice_pkg_key
        return 0
    fi
}

_choice_run() {
    local pkg
    pkg="$(_helper_pkg_json)"
    [[ -n "$pkg" ]] || return 0
    jq -b -r '(.scripts // {}) | keys[]' "$pkg" 2>/dev/null
}

_choice_workspace() {
    pnpm recursive list --json 2>/dev/null | jq -b -r '.[] | .name // empty' 2>/dev/null
}

_helper_cached_package_bins() {
    local base dir
    for base in "${XDG_CACHE_HOME:-${HOME:-}/.cache}/pnpm/dlx" "${HOME:-}/Library/Caches/pnpm/dlx" "${LOCALAPPDATA:-}/pnpm-cache/dlx"; do
        base="${base//\\//}"
        for dir in "$base"/*/pkg/node_modules/.bin; do
            [[ -d "$dir" ]] || continue
            _helper_list_bins "$dir"
        done
    done | gawk '!seen[$0]++' | head -n 200
}

_helper_list_bins() {
    local dir="$1" bin name
    for bin in "$dir"/*; do
        [[ -e "$bin" ]] || continue
        name="${bin##*/}"
        case "$name" in
            *.cmd|*.ps1) continue ;;
        esac
        printf '%s\n' "$name"
    done
}

_helper_local_package_bins() {
    local pkg dir
    pkg="$(_argc_util_path_search_parent package.json)" || return 0
    [[ -n "$pkg" ]] || return 0
    dir="${pkg%/package.json}/node_modules/.bin"
    [[ -d "$dir" ]] || return 0
    _helper_list_bins "$dir"
}

_helper_pkg_json() {
    local name="${argc_filter:-}"
    if [[ -n "$name" ]]; then
        local path
        path="$(pnpm recursive list --json 2>/dev/null | jq -b -r --arg name "$name" '.[] | select(.name == $name) | .path' 2>/dev/null | head -n 1)"
        if [[ -n "$path" && -f "$path/package.json" ]]; then
            printf '%s\n' "$path/package.json"
            return 0
        fi
    fi
    _argc_util_path_search_parent package.json
}
# <<< CHOICES

command eval "$(argc --argc-eval "$0" "$@")"
